/**
 * @param {number[][]} grid
 * @return {number}
 */
var largestMagicSquare = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let max = 0;

    const checkMagicSquare = (r, c, s) => {
        const rows = Array(s).fill(0);
        const cols = Array(s).fill(0);
        let diag1 = 0;
        let diag2 = 0;

        for (let row = 0; row < s; row++) {
            for (let col = 0; col < s; col++) {
                rows[row] += grid[row + r][col + c];
                cols[col] += grid[row + r][col + c];

                if (row === col) {
                    diag1 += grid[row + r][col + c];
                }
                if (row === s - 1 - col) {
                    diag2 += grid[row + r][col + c];
                }
            }
        }

        return diag1 === diag2 && rows.every(el => el === diag1) && cols.every(el => el === diag1);
    };

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            for (let size = Math.min(m - row, n - col); size > 0; size--) {
                if (size > max && checkMagicSquare(row, col, size)) {
                    max = size;
                    break;
                }
            }
        }
    }

    return max;
};
